package com.chronos.integration.model; import com.chronos.model.pojo.BaseEntity; import java.time.LocalDateTime; import jakarta.persistence.*; import lombok.Getter; import lombok.Setter;
@Entity @Table(name="int_sync_run") @Getter @Setter public class SyncRun extends BaseEntity { @Column(name="job_id",nullable=false,length=64) private String jobId; @Column(nullable=false,length=20) private String status="RUNNING"; @Column(name="started_at",nullable=false) private LocalDateTime startedAt=LocalDateTime.now(); @Column(name="finished_at") private LocalDateTime finishedAt; @Column(name="success_count",nullable=false) private int successCount; @Column(name="failure_count",nullable=false) private int failureCount; @Column(name="attempt_count",nullable=false) private int attemptCount; @Column(name="error_message",columnDefinition="text") private String errorMessage; }
